java.awt.Dimension size1 = param1.getSize();

net.coobird.thumbnailator.builders.ThumbnailParameterBuilder builder2 = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder();
builder2.scale(0.5);
net.coobird.thumbnailator.ThumbnailParameter param2 = builder2.build();
java.awt.Dimension size2 = param2.getSize();

assert size1 != null : "Expected non-null size for explicit dimensions";
assert size1.width == 123 && size1.height == 456 : "Incorrect explicit size";
assert size2 == null : "Expected null size for scaled parameter";

System.out.println("__CHECK__ getSize " + size1.width + "x" + size1.height + ", scaled size: " + size2);

